  queue = (track, position, playBoolean = false, tickBool = false) => {
    /*
  Create new item and add item to state's total queue 
  (updates via a call to getRecs?)
  */

    //create new item
    let artists = track.artists.map((item) => item.name);
    let item = {
      uri: track.uri,
      id: track.id,
      songDuration: track.duration_ms,
      name: track.name,
      artists: track.artists,
      image: track.album?.images?.[0],
      item: (
        <List.Item
          key={track.uri.concat("-", Date.now.toString())}
          style={{ height: "100%", border: "4px solid #0000" }}
        >
          <List.Item.Meta
            style={{ display: "block" }}
            avatar={
              <Avatar
                shape="square"
                size="large"
                src={track.album?.images?.[0]?.url}
                style={{ height: "50%", width: "150px" }}
              />
            }
            title={<p href="https://ant.design">{track.name}</p>}
            description={artists.join(", ")}
          />
        </List.Item>
      ),
    };

    //add item to total_queue
    let tempQueue = [...this.state.total_queue.slice(0, position)];
    tempQueue.push(item);
    tempQueue = [...tempQueue, ...this.state.total_queue.slice(position)];

    this.setState({ total_queue: tempQueue }, () => {
      if (playBoolean) {
        this.play(position, tickBool);
      }
      this.getRecs();
    });

    //update queue scroll to keep now playing in the middle
    //TODO: determine if this is needed
  };

  skipToFrozen() {
    /*
  "Next" into the frozen track: use Spotify's skip so it consumes the queued
  track (thawing the freeze) instead of starting a new context.
  */
    const frozen = this.state.frozenIndex;
    if (frozen == null || this.state.playLock) {
      return;
    }
    this.setState({ playLock: true, initialStart: false });
    dbgLog("bg: next -> consuming frozen");
    fetch(
      `https://api.spotify.com/v1/me/player/next?device_id=${this.state.deviceID}`,
      {
        method: "POST",
        headers: { Authorization: `Bearer ${this.accessToken}` },
      }
    )
      .then((response) => {
        if (!response.ok) {
          dbgLog(`bg: next failed ${response.status}`);
          this.setState({ playLock: false });
          return;
        }
        endSong = false;
        this.frozenQueuedUri = null;
        this.setState(
          {
            queue_pos: frozen,
            progress_ms: 0,
            playLock: false,
            current: true,
            frozenIndex: null,
          },
          () => {
            this.updateMediaSession(true);
            // `next` while paused changes the track without starting it, so
            // make sure playback actually resumes.
            if (this.state.player && this.state.player.resume) {
              this.state.player.resume();
            }
            if (document.hidden) {
              this.freezeNext();
            }
          }
        );
      })
      .catch((e) => {
        dbgLog(`bg: next error ${e && e.message}`);
        this.setState({ playLock: false });
      });
  }

  play = (queuePosition = this.state.queue_pos, tickBool = false, attempt = 0) => {
    /*
  Call spotify api to play the song at `queuePosition` via current web player (calls update playing function)
  */
    console.log(tickBool)
    this.startKeepAlive();

    if (queuePosition >= 0) {
      if (
        this.state.frozenIndex != null &&
        queuePosition === this.state.frozenIndex
      ) {
        this.skipToFrozen();
        return;
      }
      if (queuePosition >= this.state.total_queue.length) {
        this.queue(this.state.next[0], this.state.total_queue.length, true, tickBool);
      } else if (!this.state.playLock) {
          this.setState({
            // deviceID: data?.device.id ?? this.state.deviceID,
            playLock: true,
            initialStart: false,
          });
          this.state.player._options.getOAuthToken((access_token) => {
            fetch(
              `https://api.spotify.com/v1/me/player/play?device_id=${this.state.deviceID}`,
              {
                method: "PUT",
                body: JSON.stringify({
                  "uris": [this.state.total_queue[queuePosition]?.uri],
                }),
                headers: {
                  "Content-Type": "application/json",
                  Authorization: `Bearer ${access_token}`,
                },
              }
            )
              .then((response) => {
                console.log(response);
                if(!response.ok){
                  this.setState(
                    {
                      playLock: false,
                    },
                  );
                  if (attempt < 2) {
                    console.log("retrying play", response.status)
                    setTimeout(
                      () => this.play(queuePosition, tickBool, attempt + 1),
                      500
                    );
                  } else {
                    console.log("play failed, giving up", response.status);
                    dbgLog(`event: play failed ${response.status}`);
                    this.setState({ is_playing: false, progress_ms: 0 });
                    this.recoverPlayback(queuePosition);
                  }
                }
                else{
                  if(tickBool){
                    lastSecond = Date.now();
                    tickInterval = setInterval(() => this.tick(this.state.token), 1000);
                  }
                  console.log(tickBool)
                  console.log(tickInterval)
                  endSong = false;
                  this.frozenQueuedUri = null;
                  this.setState(
                    {
                      queue_pos: queuePosition,
                      progress_ms: 0,
                      playLock: false,
                      current: true,
                      frozenIndex: null,
                    },
                    () => {
                      if(debug){console.log("updating based on play function")}
                      this.updateMediaSession(true);
                      //TODO is this needed?
                      // if (!this.state.isPicklesPlayer) {
                      //   this.updatePlaying(false);
                      // }
                    }
                  );
                }
              })
            .catch((error) => {
                this.setState(
                  {
                    playLock: false,
                  },
                );
                console.log(error);
                if (attempt < 2) {
                  console.log("retrying play after error")
                  setTimeout(
                    () => this.play(queuePosition, tickBool, attempt + 1),
                    500
                  );
                } else {
                  this.setState({ is_playing: false, progress_ms: 0 });
                  this.recoverPlayback(queuePosition);
                }
              });
          });
      }
    }
  };

