  registerMediaSessionHandlers() {
    /*
  (Re)register lock-screen actions. Called after metadata so it wins over the
  SDK's own handlers, which it installs around connect(). Each action is
  guarded because support varies by platform.
  */
    if (!("mediaSession" in navigator)) {
      return;
    }
    const player = this.state.player;
    if (!player) {
      return;
    }
    const set = (action, handler) => {
      try {
        navigator.mediaSession.setActionHandler(action, handler);
      } catch (e) {
        console.log("mediaSession action not supported:", action);
      }
    };
    set("play", () => {
      if (player.activateElement) {
        player.activateElement().then(() => player.resume());
      } else {
        player.resume();
      }
    });
    set("pause", () => player.pause());
    set("previoustrack", () => this.play(this.state.queue_pos - 1));
    set("nexttrack", () => this.play(this.state.queue_pos + 1));
    set("seekto", (details) => {
      if (details && details.seekTime != null) {
        player.seek(details.seekTime);
      }
    });
  }

  updateMediaSession(isPlaying = this.state.is_playing) {
    /*
  Keep the phone / lock screen media controls in sync with the current track.
  */
    if (!("mediaSession" in navigator)) {
      return;
    }
    const track = this.state.total_queue[this.state.queue_pos];
    if (track) {
      const expectedTitle = track.name ?? "Pickles Music Player";
      try {
        navigator.mediaSession.metadata = new window.MediaMetadata({
          title: expectedTitle,
          artist:
            track.artists?.map((artist) => artist.name).join(", ") || "Pickles",
          album: "Pickles",
          artwork: [{ src: track.image?.url ?? "./images/logo.png" }],
        });
      } catch (e) {
        dbgLog(`media: SET ERROR ${e && e.message}`);
      }
      if (expectedTitle !== lastDbgTitle) {
        lastDbgTitle = expectedTitle;
        dbgLog(`media: MediaMetadata is ${typeof window.MediaMetadata}`);
        dbgLog(`media: set "${expectedTitle}"`);
        setTimeout(() => {
          const actual =
            navigator.mediaSession &&
            navigator.mediaSession.metadata &&
            navigator.mediaSession.metadata.title;
          dbgLog(
            actual === expectedTitle
              ? `media: still "${actual}" after 2s (GOOD)`
              : `media: CHANGED after 2s -> ${actual}`
          );
        }, 2000);
      }
    }
    try {
      navigator.mediaSession.playbackState = isPlaying ? "playing" : "paused";
    } catch (e) {
      dbgLog(`media: playbackState ERROR ${e && e.message}`);
    }
    if (track && track.songDuration) {
      try {
        const duration = track.songDuration / 1000;
        navigator.mediaSession.setPositionState({
          duration,
          playbackRate: 1,
          position: Math.max(0, Math.min(this.state.progress_ms / 1000, duration)),
        });
      } catch (e) {
        dbgLog(`media: positionState ERROR ${e && e.message}`);
      }
    }
    // Re-assert after the SDK's own state handling for this event has run.
    setTimeout(() => this.registerMediaSessionHandlers(), 0);
  }

  finishRecovery() {
    this.recovering = false;
    if (this.pendingPlayPosition != null) {
      const pos = this.pendingPlayPosition;
      this.pendingPlayPosition = null;
      this.play(pos);
    }
  }

  syncDevice(recover = false) {
    /*
  Refresh the device list and make sure state.deviceID points at a live
  player, adopting a reconnected SDK device or rebuilding if it is gone.
  */
    fetch(`https://api.spotify.com/v1/me/player/devices`, {
      method: "GET",
      headers: { Authorization: `Bearer ${this.state.token}` },
    })
      .then((response) => {
        if (response.status === 401) {
          this.refreshToken(0);
          throw Error("Unauthorized device sync");
        }
        return response.json();
      })
      .then((data) => {
        const devices = data.devices || [];
        this.setState({ devices });
        const ids = devices.map((device) => device.id);
        if (this.state.deviceID && ids.includes(this.state.deviceID)) {
          if (recover) {
            this.finishRecovery();
          }
          return;
        }
        const pickles = devices.find(
          (device) => device.name === "Pickles Web Player"
        );
        if (pickles) {
          this.setState({ deviceID: pickles.id }, () => {
            if (recover) {
              this.finishRecovery();
            }
          });
        } else if (recover) {
          this.rebuildPlayer();
        } else {
          console.log("device missing from player list; waiting for recovery");
        }
      })
      .catch((error) => {
        console.log("device sync failed", error);
        if (recover) {
          this.recovering = false;
        }
      });
  }

  rebuildPlayer() {
    if (Date.now() - this.lastRebuildAt < 30000) {
      this.recovering = false;
      return;
    }
    this.lastRebuildAt = Date.now();
    dbgLog("event: rebuilding player");
    if (this.state.player && this.state.player.disconnect) {
      try {
        this.state.player.disconnect();
      } catch (e) {}
    }
    this.setUpPlayer(
      {
        access_token: this.state.token,
        refresh_token: this.state.refresh_token,
      },
      false
    );
  }

