  removeFromQueue = (index) => {
    /*
  Remove the track at `index` from the app queue. If the removed track is the
  one currently playing, advance to the next one (or pause if it was the last).
  */
    const total = this.state.total_queue;
    if (index < 0 || index >= total.length) {
      return;
    }
    if (index === this.state.frozenIndex) {
      dbgLog("bg: cannot remove the frozen next");
      return;
    }
    const frozenIndexAfter =
      this.state.frozenIndex != null && index < this.state.frozenIndex
        ? this.state.frozenIndex - 1
        : this.state.frozenIndex;
    const oldPos = this.state.queue_pos;
    const newQueue = [...total.slice(0, index), ...total.slice(index + 1)];

    if (newQueue.length === 0) {
      endSong = true;
      fetch(
        `https://api.spotify.com/v1/me/player/pause?device_id=${this.state.deviceID}`,
        {
          method: "PUT",
          headers: { Authorization: `Bearer ${this.accessToken}` },
        }
      ).catch(() => {});
      this.setState({
        total_queue: [],
        queue_pos: 0,
        current: false,
        progress_ms: 0,
        is_playing: false,
      });
      this.getFirstRecs();
      return;
    }

    const newPos = index < oldPos ? oldPos - 1 : oldPos;
    this.setState(
      {
        total_queue: newQueue,
        queue_pos: newPos,
        frozenIndex: frozenIndexAfter,
      },
      () => {
      if (index === oldPos) {
        if (oldPos < newQueue.length) {
          this.play(oldPos);
        } else {
          // Removed the last queued track: fall back to the previous track,
          // shown paused so the user can choose what to play next.
          endSong = true;
          const prevPos = newQueue.length - 1;
          this.setState(
            { queue_pos: prevPos, is_playing: false, progress_ms: 0 },
            () => this.updateMediaSession(false)
          );
          fetch(
            `https://api.spotify.com/v1/me/player/pause?device_id=${this.state.deviceID}`,
            {
              method: "PUT",
              headers: { Authorization: `Bearer ${this.accessToken}` },
            }
          );
        }
      }
      this.getRecs();
    });
  };

